namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    private const int MinimumSubtotalForLoyaltyCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int Welcome5Cents = 500;
    private const int Summer10Percent = 10;
    private const int Summer10CapCents = 1_500;

    public static int TotalDiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyCents(subtotalCents, tier);
        var promoCents = PromoCents(subtotalCents - loyaltyCents, promoCode);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }

    private static int LoyaltyCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalForLoyaltyCents
            ? 0
            : Math.Min(LoyaltyDiscountPolicy.DiscountCents(subtotalCents, tier), LoyaltyCapCents);

    private static int PromoCents(int remainingCents, string? promoCode)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return Welcome5Cents;
        }

        return string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase)
            ? Math.Min(remainingCents * Summer10Percent / 100, Summer10CapCents)
            : 0;
    }
}

namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromPayableCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressCents(tier) : StandardCents(payableTotalCents, tier);

    private static int ExpressCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardCents(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromPayableCents
            ? 0
            : StandardFeeCents;
}

